@Component("refund-handler")
@ProcessingGroup("refund-processing-group")
public class RefundEventHandler {
	
	// core constructor
	RefundEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRefundEvent
     */
    @EventHandler
    public void handle( CreateRefundEvent event) {
        entityManager.persist(new Refund(event.getRefundId(), event.getRefundNumber(), event.getAmount(), event.getReason(), event.getCreatedAt(), event.getPayment(), event.getOrder(), event.getStatus()));
    }

    /*
     * @param	event UpdateRefundEvent
     */
    @EventHandler
    public Refund handle( UpdateRefundEvent event) {
    	entityManager.merge(new Refund(event.getRefundId(), event.getRefundNumber(), event.getAmount(), event.getReason(), event.getCreatedAt(), event.getPayment(), event.getOrder(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteRefundEvent
     */
    @EventHandler
    public void on( DeleteRefundEvent event) {
    	Refund entity = new Refund();
   
    	// ------------------------------------------
    	// apply the RefundId
    	// ------------------------------------------
    	entity.setRefundId( event.getRefundId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RefundRepository refundEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RefundEventHandler.class.getName());

}
